class Solution:
    def snakesAndLadders(self, board: List[List[int]]) -> int:
        n = len(board)
        target = n * n
        queue = [(1, 0)]  # (square, rolls)
        visited = {1}
        while queue:
            curr_square, rolls = queue.pop(0)
            if curr_square == target:
                return rolls
            for next_square in self.get_valid_moves(board, curr_square):
                if next_square not in visited:
                    visited.add(next_square)
                    queue.append((next_square, rolls + 1))
        return -1

    def get_valid_moves(self, board, curr_square):
        n = len(board)
        row = (curr_square - 1) // n
        col = (curr_square - 1) % n
        moves = []
        for i in range(curr_square + 1, min(curr_square + 7, n * n) ):
            next_row = (i - 1) // n
            next_col = (i - 1) % n
            if next_row == row and next_col == col:
                continue
            if board[next_row][next_col] != -1:
                moves.append(board[next_row][next_col])
            else:
                moves.append(i)
        return moves

