class Solution:
    def verticalTraversal(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []

        nodes_by_col = {}

        def traverse(node, col, row):
            if not node:
                return

            if col not in nodes_by_col:
                nodes_by_col[col] = []
            nodes_by_col[col].append((row, node.val))

            traverse(node.left, col - 1, row + 1)
            traverse(node.right, col + 1, row + 1)

        traverse(root, 0, 0)

        result = []
        for col in sorted(nodes_by_col.keys()):
            nodes_by_col[col].sort(key=lambda x: x[1])
            result.append([node[1] for node in nodes_by_col[col]])
        return result

