    def count_segments(self, n: int, x: int, arr: List[int]) -> List[int]:
        segments = [0] * (n + 1)
        for i in arr:
            segments[i] = 1
        count = 0
        result = []
        for i in range(n + 1):
            if segments[i] == 1:
                count += 1
                result.append(count)
            else:
                count = 0
        return result[:-1]

