class Solution:
    def max_possible_f(self, n: int, edges: List[List[int]], usage: List[int]) -> int:
        graph = [[] for _ in range(n + 1)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        visited = [False] * (n + 1)
        max_value = 0

        def dfs(node):
            nonlocal max_value
            visited[node] = True
            current_value = usage[node - 1]
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    current_value += dfs(neighbor)
            max_value = max(max_value, current_value)
            return current_value

        dfs(1)
        return max_value
